String str(def v) {
  if (v == null) { return null; }
  String s = v.toString();
  return s.isEmpty() ? null : s;
}
String cap(def v, int n) {
  String s = str(v);
  if (s == null) { return null; }
  return s.length() > n ? s.substring(0, n) : s;
}
def num(def v) {
  if (v == null) { return null; }
  if (v instanceof Number) { return ((Number) v).doubleValue(); }
  try { return Double.parseDouble(v.toString().trim()); } catch (Exception e) { return null; }
}
String mitreId(String s) {
  if (s == null) { return null; }
  int n = s.length();
  for (int i = 0; i + 4 < n; i++) {
    boolean boundary = i == 0 || ' ,;:/(['.indexOf(s.substring(i - 1, i)) >= 0;
    if (boundary && s.substring(i, i + 1) == 'T') {
      boolean ok = true;
      for (int j = 1; j <= 4; j++) {
        if ('0123456789'.indexOf(s.substring(i + j, i + j + 1)) < 0) { ok = false; }
      }
      if (ok) {
        int end = i + 5;
        if (end + 4 <= n && s.substring(end, end + 1) == '.') {
          boolean sub = true;
          for (int j = 1; j <= 3; j++) {
            if ('0123456789'.indexOf(s.substring(end + j, end + j + 1)) < 0) { sub = false; }
          }
          if (sub) { end = end + 4; }
        }
        return s.substring(i, end);
      }
    }
  }
  return null;
}
void putv(Map m, String k, def v) { if (v != null) { m.put(k, v); } }

boolean wrapped = ctx['analysis'] instanceof Map;
Map a = wrapped ? (Map) ctx['analysis'] : ctx;
if (a['severityAssessment'] == null) {
  throw new IllegalArgumentException('no AIIncidentAnalysis found: severityAssessment is missing');
}
String sev = a['severityAssessment'].toString().trim().toLowerCase();
if (!(sev == 'critical' || sev == 'high' || sev == 'medium' || sev == 'low')) {
  throw new IllegalArgumentException('invalid severityAssessment: ' + cap(sev, 32));
}
int lvl = sev == 'critical' ? 14 : (sev == 'high' ? 11 : (sev == 'medium' ? 8 : 5));

String engine = str(a['engineUsed']);
if (engine == null) { engine = str(ctx['engine_used']); }
if (engine == null) { engine = str(ctx['model']); }
String el = engine == null ? '' : engine.toLowerCase();
String role = null;
if (el.contains('nemotron')) { role = 'triage'; }
else if (el.contains('gemma')) { role = 'forensic'; }
else if (el.contains('heuristic') || el.startsWith('cecur') || el.contains('deterministic')) { role = 'heuristic'; }
if (role == null) {
  String r = str(ctx['role']);
  if (r != null) { r = r.toLowerCase(); }
  if (r == 'triage' || r == 'forensic' || r == 'heuristic') { role = r; }
}
if (role == null) { role = 'triage'; }
boolean fallback = ctx['fallback'] instanceof Boolean ? (boolean) ctx['fallback'] : role == 'heuristic';

String tactic = str(a['mitreTactic']);
String technique = str(a['mitreTechnique']);
String tid = mitreId(technique);
def gpu = num(a['gpuSeconds']);
if (gpu == null && wrapped) { gpu = num(ctx['gpu_seconds']); }
String alertId = str(ctx['alert_id']);
String summary = str(a['triageSummary']);

Map out = new HashMap();
out['severity'] = sev;
Map rl = new HashMap();
rl['level'] = lvl;
Map mitre = new HashMap();
if (tactic != null) { List l = new ArrayList(); l.add(tactic); mitre['tactic'] = l; }
if (technique != null) { List l = new ArrayList(); l.add(technique); mitre['technique'] = l; }
if (tid != null) { List l = new ArrayList(); l.add(tid); mitre['id'] = l; }
if (!mitre.isEmpty()) { out['mitre'] = mitre; rl['mitre'] = new HashMap(mitre); }
putv(out, 'root_cause', str(a['probableRootCause']));
putv(out, 'recommended_action', str(a['recommendedImmediateAction']));

Map ai = new HashMap();
putv(ai, 'engine', engine);
ai['role'] = role;
putv(ai, 'confidence', num(a['confidenceScore']));
ai['fallback'] = fallback;
if (wrapped) {
  putv(ai, 'verdict', str(ctx['verdict']));
  putv(ai, 'fallback_reason', str(ctx['fallback_reason']));
  putv(ai, 'request_id', str(ctx['request_id']));
}
if (a['needsVerification'] instanceof Boolean) { ai['needs_verification'] = a['needsVerification']; }
putv(ai, 'summary', cap(summary, 4000));
ai['analyzed_at'] = ctx['@timestamp'];
if (gpu != null) {
  Map cost = new HashMap();
  cost['gpu_seconds'] = gpu;
  ai['cost'] = cost;
}
out['ai'] = ai;

String id = alertId;
if (alertId != null) {
  out['id'] = alertId;
} else {
  id = str(ctx['request_id']);
  putv(out, 'id', id);
  out['@timestamp'] = ctx['@timestamp'];
  Map src = new HashMap();
  src['system'] = 'cs3-ai';
  src['stream'] = 'cs3.ai.inference';
  out['source'] = src;
  putv(rl, 'description', cap(summary, 8000));
  putv(out, 'full_log', cap(summary, 8000));
}
out['rule'] = rl;

def keepError = ctx['ingest_error'];
for (def k : new ArrayList(ctx.keySet())) {
  if (!k.startsWith('_')) { ctx.remove(k); }
}
ctx.putAll(out);
if (keepError != null) { ctx['ingest_error'] = keepError; }
if (alertId == null && id != null) { ctx['_id'] = id; }
